/**
 * Get mock tasks array
 */
export const getMockTasks = (): Task[] => {
  return mockTasks;
};

/**
 * Get mock task by ID
 */
export const getMockTaskById = (id: string): Task | undefined => {
  return mockTasks.find((t) => t.id === id);
};

/**
 * Mock task stats
 */
export const getMockTaskStats = () => {
  return {
    total: mockTasks.length,
    created: mockTasks.filter((t) => t.status === TaskStatus.Created).length,
    assigned: mockTasks.filter((t) => t.status === TaskStatus.Assigned).length,
    inProgress: mockTasks.filter((t) => t.status === TaskStatus.InProgress).length,
    supportRequested: mockTasks.filter((t) => t.status === TaskStatus.SupportRequested).length,
    collabAssigned: mockTasks.filter((t) => t.status === TaskStatus.CollabAssigned).length,
    blocked: mockTasks.filter((t) => t.status === TaskStatus.Blocked).length,
    underReview: mockTasks.filter((t) => t.status === TaskStatus.UnderReview).length,
    changesRequested: mockTasks.filter((t) => t.status === TaskStatus.ChangesRequested).length,
    completed: mockTasks.filter((t) => t.status === TaskStatus.Completed).length,
    cancelled: mockTasks.filter((t) => t.status === TaskStatus.Cancelled).length,
  };
};
