import React, { useState } from 'react';
import { UUID } from '../../../models/common';
import { Button } from '../../common/Button';
import { TabSlideout } from '../TabSlideout';
import styles from './ChatTab.module.css';

export interface ChatMessage {
  id: UUID;
  entityId: UUID; // Can be ticketId or taskId
  userId: string;
  userName: string;
  userAvatar?: string;
  message: string;
  timestamp: string;
}

export interface ChatTabProps {
  entityId: UUID;
  entityType: 'ticket' | 'task';
  messages?: ChatMessage[];
  onSendMessage?: (message: string) => Promise<void>;
  onDeleteMessage?: (messageId: UUID) => Promise<void>;
  currentUserId?: string; // Current logged-in user ID to align messages
}

export const ChatTab: React.FC<ChatTabProps> = ({
  entityId: _entityId,
  entityType,
  messages = [],
  onSendMessage,
  onDeleteMessage: _onDeleteMessage,
  currentUserId = 'user-001', // Default for demo, should come from auth context
}) => {
  const [message, setMessage] = useState('');
  const [sending, setSending] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!message.trim()) return;

    setSending(true);
    try {
      if (onSendMessage) {
        await onSendMessage(message.trim());
      }
      setMessage('');
    } catch (error) {
      console.error('Failed to send message:', error);
    } finally {
      setSending(false);
    }
  };

  const formatTime = (timestamp: string) => {
    const date = new Date(timestamp);
    return date.toLocaleTimeString('vi-VN', {
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const getAvatarColor = (userId: string) => {
    const colors = [
      'var(--blue-500)',
      'var(--green-500)',
      'var(--purple-500)',
      'var(--orange-500)',
      'var(--pink-500)',
      'var(--teal-500)',
    ];
    const hash = userId.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
    return colors[hash % colors.length];
  };

  const getInitials = (name: string) => {
    const parts = name.split(' ');
    if (parts.length >= 2) {
      return parts[0][0] + parts[parts.length - 1][0];
    }
    return name.substring(0, 2);
  };

  const entityLabel = entityType === 'ticket' ? 'phiếu' : 'task';

  const isOwnMessage = (msg: ChatMessage) => {
    return msg.userId === currentUserId;
  };

  const footerContent = (
    <div className={styles.footer}>
      <div className={styles.hint}>
        <i className="fas fa-info-circle"></i>
        <span>Sử dụng @tên để mention thành viên khác</span>
      </div>
      <form onSubmit={handleSubmit} className={styles.form}>
        <input
          type="text"
          className={styles.input}
          placeholder="Nhập tin nhắn nhanh..."
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          disabled={sending}
        />
        <Button type="submit" disabled={!message.trim() || sending} size="md">
          {sending ? (
            <>
              <i className="fas fa-spinner fa-spin"></i> Đang gửi...
            </>
          ) : (
            <>
              <i className="fas fa-paper-plane"></i> Gửi
            </>
          )}
        </Button>
      </form>
    </div>
  );

  return (
    <TabSlideout footer={footerContent} className={styles.chatTab}>
      <div className={styles.messages}>
        {messages.length === 0 ? (
          <div className={styles.empty}>
            <i className="fas fa-comments"></i>
            <p>Chưa có tin nhắn nào</p>
            <span>Bắt đầu trao đổi về {entityLabel} này</span>
          </div>
        ) : (
          messages.map((msg) => {
            const isOwn = isOwnMessage(msg);
            return (
              <div key={msg.id} className={`${styles.message} ${isOwn ? styles.messageOwn : styles.messageOther}`}>
                {!isOwn && (
                  <div
                    className={styles.avatar}
                    style={{ backgroundColor: getAvatarColor(msg.userId) }}
                  >
                    {msg.userAvatar || getInitials(msg.userName)}
                  </div>
                )}
                <div className={styles.messageContent}>
                  {!isOwn && (
                    <div className={styles.messageHeader}>
                      <span className={styles.userName}>{msg.userName}</span>
                      <span className={styles.timestamp}>{formatTime(msg.timestamp)}</span>
                    </div>
                  )}
                  <div className={styles.messageBody}>
                    {msg.message}
                    {isOwn && (
                      <span className={styles.ownTimestamp}>{formatTime(msg.timestamp)}</span>
                    )}
                  </div>
                </div>
              </div>
            );
          })
        )}
      </div>
    </TabSlideout>
  );
};
