import React from 'react';
import { StatsCard, StatsCardsGrid } from '../../../components/common';

interface TaskStatsCardsProps {
  stats: {
    total: number;
    assigned: number;
    inProgress: number;
    completed: number;
    overdue: number;
  };
  loading?: boolean;
}

export const TaskStatsCards: React.FC<TaskStatsCardsProps> = ({ stats, loading }) => {
  return (
    <StatsCardsGrid>
      <StatsCard 
        label="Total Tasks" 
        value={stats.total} 
        icon="fas fa-tasks" 
        variant="total" 
        loading={loading} 
      />
      <StatsCard 
        label="Đã Giao" 
        value={stats.assigned} 
        icon="fas fa-user-check" 
        variant="info" 
        loading={loading} 
      />
      <StatsCard 
        label="Đang Thực Hiện" 
        value={stats.inProgress} 
        icon="fas fa-spinner" 
        variant="warning" 
        loading={loading} 
      />
      <StatsCard 
        label="Hoàn Thành" 
        value={stats.completed} 
        icon="fas fa-check-circle" 
        variant="success" 
        loading={loading} 
      />
      <StatsCard 
        label="Quá Hạn" 
        value={stats.overdue} 
        icon="fas fa-exclamation-triangle" 
        variant="danger" 
        loading={loading} 
      />
    </StatsCardsGrid>
  );
};
