import React, { useEffect, useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import {
  fetchApprovals,
  fetchApprovalStats,
  approveApproval,
  rejectApproval,
  requestChanges,
  bulkApprovalAction,
  setFilters,
} from '../../store/slices/approvalsSlice';
import { Approval, ApprovalStatus } from '../../models/Approval';
import { ApprovalCard } from '../../components/approvals/ApprovalCard';
import {
  ApproveModal,
  RejectModal,
  RequestChangesModal,
  BulkApproveModal,
} from '../../components/approvals/ApprovalActionModals';
import { Button, Tabs, Tab } from '../../components/common';
import { useToast } from '../../components/common/Toast';
import styles from './ApprovalsPage.module.css';

const ApprovalsPage: React.FC = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const { items, stats, filters, loading, actionLoading } = useAppSelector(
    (state) => state.approvals
  );
  const { showToast } = useToast();

  const [activeTab, setActiveTab] = useState<ApprovalStatus>(ApprovalStatus.Pending);
  const [selectedApproval, setSelectedApproval] = useState<Approval | null>(null);
  const [approveModalOpen, setApproveModalOpen] = useState(false);
  const [rejectModalOpen, setRejectModalOpen] = useState(false);
  const [changesModalOpen, setChangesModalOpen] = useState(false);
  const [bulkApproveModalOpen, setBulkApproveModalOpen] = useState(false);

  useEffect(() => {
    dispatch(fetchApprovalStats());
    dispatch(
      fetchApprovals({
        filters: { ...filters, status: activeTab },
      })
    );
  }, [dispatch, activeTab]);

  const handleTabChange = (tab: ApprovalStatus) => {
    setActiveTab(tab);
    dispatch(setFilters({ ...filters, status: tab }));
  };

  const handleApprove = (approval: Approval) => {
    setSelectedApproval(approval);
    setApproveModalOpen(true);
  };

  const handleReject = (approval: Approval) => {
    setSelectedApproval(approval);
    setRejectModalOpen(true);
  };

  const handleRequestChanges = (approval: Approval) => {
    setSelectedApproval(approval);
    setChangesModalOpen(true);
  };

  const handleViewDetails = (approvalId: string) => {
    // Navigate to related entity (task, ticket, etc.)
    const approval = items.find((a) => a.id === approvalId);
    if (approval?.relatedEntityType === 'task' && approval.relatedEntityId) {
      navigate(`/tasks/${approval.relatedEntityId}`);
    }
  };

  const confirmApprove = async (note?: string) => {
    if (!selectedApproval) return;

    try {
      await dispatch(
        approveApproval({
          approvalId: selectedApproval.id,
          note,
        })
      ).unwrap();
      showToast('Đã chấp nhận yêu cầu thành công', 'success');
      setApproveModalOpen(false);
      setSelectedApproval(null);
      // Refresh data
      dispatch(fetchApprovalStats());
      dispatch(
        fetchApprovals({
          filters: { ...filters, status: activeTab },
        })
      );
    } catch (error) {
      showToast('Không thể chấp nhận yêu cầu. Vui lòng thử lại!', 'error');
    }
  };

  const confirmReject = async (reason: string) => {
    if (!selectedApproval) return;

    try {
      await dispatch(
        rejectApproval({
          approvalId: selectedApproval.id,
          reason,
        })
      ).unwrap();
      showToast('Đã từ chối yêu cầu', 'success');
      setRejectModalOpen(false);
      setSelectedApproval(null);
      // Refresh data
      dispatch(fetchApprovalStats());
      dispatch(
        fetchApprovals({
          filters: { ...filters, status: activeTab },
        })
      );
    } catch (error) {
      showToast('Không thể từ chối yêu cầu. Vui lòng thử lại!', 'error');
    }
  };

  const confirmRequestChanges = async (changes: string) => {
    if (!selectedApproval) return;

    try {
      await dispatch(
        requestChanges({
          approvalId: selectedApproval.id,
          changes,
        })
      ).unwrap();
      showToast('Đã gửi yêu cầu sửa đổi', 'success');
      setChangesModalOpen(false);
      setSelectedApproval(null);
      // Refresh data
      dispatch(
        fetchApprovals({
          filters: { ...filters, status: activeTab },
        })
      );
    } catch (error) {
      showToast('Không thể gửi yêu cầu sửa đổi. Vui lòng thử lại!', 'error');
    }
  };

  const handleBulkApprove = () => {
    setBulkApproveModalOpen(true);
  };

  const confirmBulkApprove = async (note?: string) => {
    const pendingApprovals = items.filter((a) => a.status === ApprovalStatus.Pending);
    const approvalIds = pendingApprovals.map((a) => a.id);

    if (approvalIds.length === 0) {
      showToast('Không có yêu cầu nào để phê duyệt', 'warning');
      return;
    }

    try {
      await dispatch(
        bulkApprovalAction({
          approvalIds,
          action: 'approve',
          note,
        })
      ).unwrap();
      showToast(`Đã chấp nhận ${approvalIds.length} yêu cầu`, 'success');
      setBulkApproveModalOpen(false);
      // Refresh data
      dispatch(fetchApprovalStats());
      dispatch(
        fetchApprovals({
          filters: { ...filters, status: activeTab },
        })
      );
    } catch (error) {
      showToast('Không thể thực hiện phê duyệt hàng loạt. Vui lòng thử lại!', 'error');
    }
  };

  const pendingCount = stats?.pending || 0;
  const approvedTodayCount = stats?.approvedToday || 0;
  const rejectedTodayCount = stats?.rejectedToday || 0;
  const approvalRate = stats?.approvalRate || 0;

  // Configure tabs with overflow detection support
  const approvalTabs: Tab[] = useMemo(
    () => [
      {
        id: ApprovalStatus.Pending,
        label: 'Chờ phê duyệt',
        badge: pendingCount,
        badgeColor: 'warning' as const,
      },
      {
        id: ApprovalStatus.Approved,
        label: 'Đã chấp nhận',
        badge: approvedTodayCount,
        badgeColor: 'success' as const,
      },
      {
        id: ApprovalStatus.Rejected,
        label: 'Đã từ chối',
        badge: rejectedTodayCount,
        badgeColor: 'gray' as const,
      },
    ],
    [pendingCount, approvedTodayCount, rejectedTodayCount]
  );

  return (
    <div className={styles.container}>
      {/* Header */}
      <div className={styles.header}>
        <div className={styles.headerContent}>
          <h1 className={styles.title}>
            <i className="fas fa-check-double"></i>
            Phê duyệt
          </h1>
          <p className={styles.subtitle}>Quản lý và xử lý các yêu cầu phê duyệt</p>
        </div>
        {pendingCount > 0 && (
          <div className={styles.headerActions}>
            <Button variant="success" onClick={handleBulkApprove}>
              <i className="fas fa-check-double"></i>
              Chấp nhận tất cả ({pendingCount})
            </Button>
          </div>
        )}
      </div>

      {/* Stats */}
      <div className={styles.statsGrid}>
        <div className={styles.statCard}>
          <div className={styles.statIcon} style={{ background: 'var(--warning-light)' }}>
            <i className="fas fa-clock" style={{ color: 'var(--warning-color)' }}></i>
          </div>
          <div className={styles.statInfo}>
            <div className={styles.statLabel}>Chờ phê duyệt</div>
            <div className={styles.statValue}>{pendingCount}</div>
          </div>
        </div>
        <div className={styles.statCard}>
          <div className={styles.statIcon} style={{ background: '#dcfce7' }}>
            <i className="fas fa-check-circle" style={{ color: 'var(--success-color)' }}></i>
          </div>
          <div className={styles.statInfo}>
            <div className={styles.statLabel}>Đã chấp nhận (hôm nay)</div>
            <div className={styles.statValue}>{approvedTodayCount}</div>
          </div>
        </div>
        <div className={styles.statCard}>
          <div className={styles.statIcon} style={{ background: '#fee2e2' }}>
            <i className="fas fa-times-circle" style={{ color: 'var(--danger-color)' }}></i>
          </div>
          <div className={styles.statInfo}>
            <div className={styles.statLabel}>Đã từ chối (hôm nay)</div>
            <div className={styles.statValue}>{rejectedTodayCount}</div>
          </div>
        </div>
        <div className={styles.statCard}>
          <div className={styles.statIcon} style={{ background: 'var(--primary-light)' }}>
            <i className="fas fa-percentage" style={{ color: 'var(--primary-color)' }}></i>
          </div>
          <div className={styles.statInfo}>
            <div className={styles.statLabel}>Tỷ lệ chấp nhận</div>
            <div className={styles.statValue}>{approvalRate}%</div>
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div className={styles.tabsCard}>
        <Tabs
          tabs={approvalTabs}
          activeTab={activeTab}
          onTabChange={(tabId) => handleTabChange(tabId as ApprovalStatus)}
          variant="default"
        />
      </div>

      {/* Content */}
      <div className={styles.content}>
        {loading && <div className={styles.loading}>Đang tải...</div>}

        {!loading && items.length === 0 && (
          <div className={styles.empty}>
            <i className="fas fa-inbox"></i>
            <p>Không có yêu cầu phê duyệt nào</p>
          </div>
        )}

        {!loading &&
          items.length > 0 &&
          items
            .filter((a) => a.status === activeTab)
            .map((approval) => (
              <ApprovalCard
                key={approval.id}
                approval={approval}
                onApprove={() => handleApprove(approval)}
                onReject={() => handleReject(approval)}
                onRequestChanges={
                  activeTab === ApprovalStatus.Pending
                    ? () => handleRequestChanges(approval)
                    : undefined
                }
                onViewDetails={() => handleViewDetails(approval.id)}
              />
            ))}
      </div>

      {/* Modals */}
      <ApproveModal
        isOpen={approveModalOpen}
        onClose={() => {
          setApproveModalOpen(false);
          setSelectedApproval(null);
        }}
        onConfirm={confirmApprove}
        approvalTitle={selectedApproval?.title || ''}
        loading={actionLoading}
      />

      <RejectModal
        isOpen={rejectModalOpen}
        onClose={() => {
          setRejectModalOpen(false);
          setSelectedApproval(null);
        }}
        onConfirm={confirmReject}
        approvalTitle={selectedApproval?.title || ''}
        loading={actionLoading}
      />

      <RequestChangesModal
        isOpen={changesModalOpen}
        onClose={() => {
          setChangesModalOpen(false);
          setSelectedApproval(null);
        }}
        onConfirm={confirmRequestChanges}
        approvalTitle={selectedApproval?.title || ''}
        loading={actionLoading}
      />

      <BulkApproveModal
        isOpen={bulkApproveModalOpen}
        onClose={() => setBulkApproveModalOpen(false)}
        onConfirm={confirmBulkApprove}
        count={pendingCount}
        loading={actionLoading}
      />
    </div>
  );
};

export default ApprovalsPage;
