/**
 * Get mock user settings by user ID
 */
export const getMockUserSettings = (userId: string): UserSettings => {
  // Return specific mock data if available
  const mockData = Object.values(mockUserSettingsVariations).find(
    (settings) => settings.userId === userId
  );

  if (mockData) {
    return mockData;
  }

  // Return default mock data
  return {
    ...mockUserSettings,
    userId,
  };
};
