import React, { useState, useMemo } from 'react';
import { Task } from '../../../models/Task';
import { Card, Tabs, Tab } from '../../../components/common';
import { ChatTab, ChatMessage, CommentsTab, ActivityTab, AttachmentsTab } from '../../../components/shared';
import { ChecklistTab } from './ChecklistTab';
import { SubtaskState } from '../types';
import { TabType, getMockChatMessages, getMockComments } from '../utils';
import styles from './TaskTabs.module.css';

interface TaskTabsProps {
  task: Task;
  // Checklist props
  editingSubtasks: Map<string, SubtaskState>;
  newSubtaskTitle: string;
  onToggleSubtask: (subtaskId: string) => Promise<void>;
  onAddSubtask: () => Promise<void>;
  onDeleteSubtask: (subtaskId: string) => Promise<void>;
  onStartEdit: (subtaskId: string, currentTitle: string) => void;
  onCancelEdit: (subtaskId: string) => void;
  onSaveEdit: (subtaskId: string) => Promise<void>;
  onEditTitleChange: (subtaskId: string, value: string) => void;
  onNewSubtaskChange: (value: string) => void;
  isProcessing: boolean;
}

const TaskTabs: React.FC<TaskTabsProps> = ({
  task,
  editingSubtasks,
  newSubtaskTitle,
  onToggleSubtask,
  onAddSubtask,
  onDeleteSubtask,
  onStartEdit,
  onCancelEdit,
  onSaveEdit,
  onEditTitleChange,
  onNewSubtaskChange,
  isProcessing,
}) => {
  const [activeTab, setActiveTab] = useState<TabType>('checklist');

  // Mock data for tabs
  const mockChatMessages: ChatMessage[] = useMemo(() => getMockChatMessages(task.id), [task.id]);
  const mockComments = useMemo(() => getMockComments(task.id), [task.id]);

  // Define tabs configuration with overflow detection support
  const tabs: Tab[] = useMemo(
    () => [
      {
        id: 'checklist',
        label: 'Checklist',
        icon: 'fas fa-tasks',
        badge: task.subtasks?.filter((st) => !st.completed).length || 0,
        badgeColor: 'primary' as const,
      },
      {
        id: 'chat',
        label: 'Trao đổi',
        icon: 'fas fa-comments',
        badge: mockChatMessages.length,
        badgeColor: 'primary' as const,
      },
      {
        id: 'comments',
        label: 'Bình luận',
        icon: 'fas fa-comment-dots',
        badge: mockComments.length || 0,
        badgeColor: 'gray' as const,
      },
      {
        id: 'attachments',
        label: 'Files',
        icon: 'fas fa-paperclip',
        badge: 0, // TODO: Add attachments count when available
        badgeColor: 'gray' as const,
      },
      {
        id: 'activity',
        label: 'Activity',
        icon: 'fas fa-history',
      },
    ],
    [task.subtasks, mockChatMessages.length, mockComments.length]
  );

  const renderTabContent = () => {
    switch (activeTab) {
      case 'checklist':
        return (
          <ChecklistTab
            task={task}
            editingSubtasks={editingSubtasks}
            newSubtaskTitle={newSubtaskTitle}
            onToggleSubtask={onToggleSubtask}
            onAddSubtask={onAddSubtask}
            onDeleteSubtask={onDeleteSubtask}
            onStartEdit={onStartEdit}
            onCancelEdit={onCancelEdit}
            onSaveEdit={onSaveEdit}
            onEditTitleChange={onEditTitleChange}
            onNewSubtaskChange={onNewSubtaskChange}
            isProcessing={isProcessing}
          />
        );
      case 'chat':
        return (
          <ChatTab
            entityId={task.id}
            entityType="task"
            messages={mockChatMessages}
            onSendMessage={async (message) => {
              console.log('Send task chat message:', message);
              // TODO: Call API to send message
            }}
          />
        );
      case 'comments':
        return (
          <CommentsTab
            entityId={task.id}
            entityType="task"
            comments={mockComments}
            onAddComment={async (content, parentId) => {
              console.log('Add task comment:', content, parentId);
              // TODO: Call API to add comment
            }}
          />
        );
      case 'activity':
        return (
          <ActivityTab
            entityId={task.id}
            entityType="task"
            activities={[]}
          />
        );
      case 'attachments':
        return (
          <AttachmentsTab
            entityId={task.id}
            entityType="task"
            attachments={[]}
            onUpload={async (files) => {
              console.log('Upload task files:', files);
              // TODO: Call API to upload files
            }}
          />
        );
      default:
        return null;
    }
  };

  return (
    <Card>
      <div className={styles.tabsHeader}>
        <Tabs
          tabs={tabs}
          activeTab={activeTab}
          onTabChange={(tabId) => setActiveTab(tabId as TabType)}
          variant="underline"
        />
      </div>
      <div className={styles.tabContent}>{renderTabContent()}</div>
    </Card>
  );
};

export default TaskTabs;
