/**
 * Filter history items
 */
export const filterHistoryItems = (
  items: HistoryItem[],
  search?: string,
  type?: HistoryItemType,
  priority?: TicketPriority | TaskPriority
): HistoryItem[] => {
  let filtered = [...items];

  if (search) {
    const searchLower = search.toLowerCase();
    filtered = filtered.filter(
      (item) =>
        item.entityCode.toLowerCase().includes(searchLower) ||
        item.entityTitle.toLowerCase().includes(searchLower) ||
        item.actionDescription.toLowerCase().includes(searchLower)
    );
  }

  if (type) {
    filtered = filtered.filter((item) => item.type === type);
  }

  if (priority) {
    filtered = filtered.filter((item) => item.priority === priority);
  }

  return filtered;
};
