/**
 * Custom hook for managing task subtasks (checklist operations)
 */

import { useState } from 'react';
import { useAppDispatch } from '../../../store/hooks';
import { updateTask } from '../../../store/slices/tasksSlice';
import { Subtask } from '../../../models/Task';
import { SubtaskState } from '../types';

interface UseSubtaskManagerProps {
  taskId: string;
  subtasks: Subtask[];
}

interface UseSubtaskManagerReturn {
  // State
  editingSubtasks: Map<string, SubtaskState>;
  newSubtaskTitle: string;
  setNewSubtaskTitle: (title: string) => void;
  isProcessing: boolean;
  
  // Handlers
  handleToggleSubtask: (subtaskId: string) => Promise<void>;
  handleAddSubtask: () => Promise<void>;
  handleDeleteSubtask: (subtaskId: string) => Promise<void>;
  handleStartEditSubtask: (subtaskId: string, currentTitle: string) => void;
  handleCancelEditSubtask: (subtaskId: string) => void;
  handleSaveEditSubtask: (subtaskId: string) => Promise<void>;
  handleEditTitleChange: (subtaskId: string, newTitle: string) => void;
}

/**
 * Hook to manage subtask CRUD operations
 * @param taskId - Current task ID
 * @param subtasks - Array of subtasks
 * @returns Subtask management state and handlers
 */
export const useSubtaskManager = ({
  taskId,
  subtasks,
}: UseSubtaskManagerProps): UseSubtaskManagerReturn => {
  const dispatch = useAppDispatch();
  const [editingSubtasks, setEditingSubtasks] = useState<Map<string, SubtaskState>>(new Map());
  const [newSubtaskTitle, setNewSubtaskTitle] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);

  /**
   * Toggle subtask completion status
   */
  const handleToggleSubtask = async (subtaskId: string) => {
    if (!taskId) return;
    
    setIsProcessing(true);
    const updatedSubtasks = subtasks.map((st) =>
      st.id === subtaskId ? { ...st, completed: !st.completed } : st
    );

    try {
      await dispatch(
        updateTask({
          id: taskId,
          data: { subtasks: updatedSubtasks },
        })
      ).unwrap();
    } catch (error) {
      console.error('Failed to toggle subtask:', error);
    } finally {
      setIsProcessing(false);
    }
  };

  /**
   * Add new subtask
   */
  const handleAddSubtask = async () => {
    if (!taskId || !newSubtaskTitle.trim()) return;

    setIsProcessing(true);
    const newSubtask: Subtask = {
      id: String(Date.now()),
      title: newSubtaskTitle.trim(),
      completed: false,
    };

    const updatedSubtasks = [...subtasks, newSubtask];

    try {
      await dispatch(
        updateTask({
          id: taskId,
          data: { subtasks: updatedSubtasks },
        })
      ).unwrap();
      setNewSubtaskTitle('');
    } catch (error) {
      console.error('Failed to add subtask:', error);
    } finally {
      setIsProcessing(false);
    }
  };

  /**
   * Delete subtask
   */
  const handleDeleteSubtask = async (subtaskId: string) => {
    if (!taskId) return;

    setIsProcessing(true);
    const updatedSubtasks = subtasks.filter((st) => st.id !== subtaskId);

    try {
      await dispatch(
        updateTask({
          id: taskId,
          data: { subtasks: updatedSubtasks },
        })
      ).unwrap();
    } catch (error) {
      console.error('Failed to delete subtask:', error);
    } finally {
      setIsProcessing(false);
    }
  };

  /**
   * Start editing subtask
   */
  const handleStartEditSubtask = (subtaskId: string, currentTitle: string) => {
    const newMap = new Map(editingSubtasks);
    newMap.set(subtaskId, { isEditing: true, title: currentTitle });
    setEditingSubtasks(newMap);
  };

  /**
   * Cancel editing subtask
   */
  const handleCancelEditSubtask = (subtaskId: string) => {
    const newMap = new Map(editingSubtasks);
    newMap.delete(subtaskId);
    setEditingSubtasks(newMap);
  };

  /**
   * Save edited subtask
   */
  const handleSaveEditSubtask = async (subtaskId: string) => {
    if (!taskId) return;
    
    const editState = editingSubtasks.get(subtaskId);
    if (!editState || !editState.title.trim()) return;

    setIsProcessing(true);
    const updatedSubtasks = subtasks.map((st) =>
      st.id === subtaskId ? { ...st, title: editState.title.trim() } : st
    );

    try {
      await dispatch(
        updateTask({
          id: taskId,
          data: { subtasks: updatedSubtasks },
        })
      ).unwrap();
      handleCancelEditSubtask(subtaskId);
    } catch (error) {
      console.error('Failed to edit subtask:', error);
    } finally {
      setIsProcessing(false);
    }
  };

  /**
   * Update edit title change
   */
  const handleEditTitleChange = (subtaskId: string, newTitle: string) => {
    const editState = editingSubtasks.get(subtaskId);
    if (editState) {
      const newMap = new Map(editingSubtasks);
      newMap.set(subtaskId, { ...editState, title: newTitle });
      setEditingSubtasks(newMap);
    }
  };

  return {
    editingSubtasks,
    newSubtaskTitle,
    setNewSubtaskTitle,
    isProcessing,
    handleToggleSubtask,
    handleAddSubtask,
    handleDeleteSubtask,
    handleStartEditSubtask,
    handleCancelEditSubtask,
    handleSaveEditSubtask,
    handleEditTitleChange,
  };
};
