import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  HelpArticle,
  HelpCategoryInfo,
  HelpSearchResult,
} from '../../models/Help';
import { helpService } from '../../services/helpService';
import { SearchBar } from '../../components/help/SearchBar';
import { CategoryGrid } from '../../components/help/CategoryGrid';
import { FeaturedArticles } from '../../components/help/FeaturedArticles';
import { QuickLinks } from '../../components/help/QuickLinks';
import { ContactSupportPanel } from '../../components/help/ContactSupportPanel';
import styles from './HelpCenterPage.module.css';

export const HelpCenterPage: React.FC = () => {
  const navigate = useNavigate();
  const [categories, setCategories] = useState<HelpCategoryInfo[]>([]);
  const [featuredArticles, setFeaturedArticles] = useState<HelpArticle[]>([]);
  const [searchResults, setSearchResults] = useState<HelpSearchResult[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [loading, setLoading] = useState(true);
  const [searching, setSearching] = useState(false);
  const [contactPanelOpen, setContactPanelOpen] = useState(false);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const [categoriesData, featuredData] = await Promise.all([
        helpService.getCategories(),
        helpService.getArticles(undefined, true),
      ]);
      
      setCategories(categoriesData);
      setFeaturedArticles(featuredData);
    } catch (error) {
      console.error('Failed to load help center data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = async (query: string) => {
    setSearchQuery(query);
    
    if (!query || query.length < 2) {
      setSearchResults([]);
      return;
    }

    try {
      setSearching(true);
      const results = await helpService.search(query);
      setSearchResults(results);
    } catch (error) {
      console.error('Search failed:', error);
    } finally {
      setSearching(false);
    }
  };

  const handleResultClick = (result: HelpSearchResult) => {
    navigate(result.url);
    setSearchQuery('');
    setSearchResults([]);
  };

  if (loading) {
    return (
      <div className={styles.helpCenter}>
        <div className={styles.loading}>Đang tải...</div>
      </div>
    );
  }

  return (
    <div className={styles.helpCenter}>
      {/* Hero Section */}
      <div className={styles.hero}>
        <h1 className={styles.heroTitle}>Trung tâm Trợ giúp</h1>
        <p className={styles.heroSubtitle}>
          Tìm câu trả lời cho các câu hỏi của bạn
        </p>
        
        <div className={styles.heroSearch}>
          <SearchBar
            value={searchQuery}
            onChange={handleSearch}
            searching={searching}
            results={searchResults}
            onResultClick={handleResultClick}
          />
        </div>
      </div>

      {/* Quick Links */}
      <QuickLinks onContactClick={() => setContactPanelOpen(true)} />

      {/* Categories Grid */}
      <section className={styles.section}>
        <h2 className={styles.sectionTitle}>Danh mục</h2>
        <CategoryGrid categories={categories} />
      </section>

      {/* Featured Articles */}
      {featuredArticles.length > 0 && (
        <section className={styles.section}>
          <h2 className={styles.sectionTitle}>Bài viết nổi bật</h2>
          <FeaturedArticles articles={featuredArticles} />
        </section>
      )}

      {/* Still Need Help */}
      <section className={styles.contactSection}>
        <h2>Vẫn cần trợ giúp?</h2>
        <p>Liên hệ với đội ngũ hỗ trợ của chúng tôi</p>
        <button
          className={styles.contactButton}
          onClick={() => setContactPanelOpen(true)}
        >
          Gửi yêu cầu hỗ trợ
        </button>
      </section>

      {/* Contact Support Panel */}
      <ContactSupportPanel
        isOpen={contactPanelOpen}
        onClose={() => setContactPanelOpen(false)}
      />
    </div>
  );
};
