import React from 'react';
import { useNavigate } from 'react-router-dom';
import { HelpArticle } from '../../../models/Help';
import { getCategoryInfo } from '../../../models/Help';
import styles from './FeaturedArticles.module.css';

interface FeaturedArticlesProps {
  articles: HelpArticle[];
}

export const FeaturedArticles: React.FC<FeaturedArticlesProps> = ({ articles }) => {
  const navigate = useNavigate();

  const handleArticleClick = (slug: string) => {
    navigate(`/help/articles/${slug}`);
  };

  return (
    <div className={styles.featured}>
      {articles.map((article) => {
        const categoryInfo = getCategoryInfo(article.category);
        
        return (
          <div
            key={article.id}
            className={styles.article}
            onClick={() => handleArticleClick(article.slug)}
          >
            <div className={styles.header}>
              <span className={styles.categoryBadge}>
                <i className={categoryInfo.icon} /> {categoryInfo.label}
              </span>
              {article.featured && (
                <span className={styles.featuredBadge}>⭐ Nổi bật</span>
              )}
            </div>
            
            <h3 className={styles.title}>{article.title}</h3>
            <p className={styles.description}>{article.description}</p>
            
            <div className={styles.meta}>
              <span className={styles.views}>👁 {article.viewCount} lượt xem</span>
              <span className={styles.readTime}>⏱ {article.readTime} phút</span>
            </div>
          </div>
        );
      })}
    </div>
  );
};
