/**
 * HistoryStatsCards Component
 * Summary statistics cards for work history
 */

import React from 'react';
import { HistoryStats } from '../../../models/History';
import styles from './HistoryStatsCards.module.css';

interface HistoryStatsCardsProps {
  stats: HistoryStats;
}

export const HistoryStatsCards: React.FC<HistoryStatsCardsProps> = ({ stats }) => {
  return (
    <div className={styles.statsGrid}>
      <div className={styles.statCard}>
        <div className={styles.statIcon} style={{ background: 'var(--primary-light)' }}>
          <i className="fas fa-check-circle" style={{ color: 'var(--primary-color)' }}></i>
        </div>
        <div className={styles.statInfo}>
          <div className={styles.statLabel}>Tổng đã hoàn thành</div>
          <div className={styles.statValue}>{stats.totalCompleted}</div>
        </div>
      </div>

      <div className={styles.statCard}>
        <div className={styles.statIcon} style={{ background: '#dcfce7' }}>
          <i className="fas fa-calendar-check" style={{ color: 'var(--success-color)' }}></i>
        </div>
        <div className={styles.statInfo}>
          <div className={styles.statLabel}>Tháng này</div>
          <div className={styles.statValue}>{stats.completedThisMonth}</div>
        </div>
      </div>

      <div className={styles.statCard}>
        <div className={styles.statIcon} style={{ background: '#fef3c7' }}>
          <i className="fas fa-clock" style={{ color: 'var(--warning-color)' }}></i>
        </div>
        <div className={styles.statInfo}>
          <div className={styles.statLabel}>Tổng thời gian</div>
          <div className={styles.statValue}>{stats.totalTimeSpent}h</div>
        </div>
      </div>

      <div className={styles.statCard}>
        <div className={styles.statIcon} style={{ background: '#dbeafe' }}>
          <i className="fas fa-star" style={{ color: '#fbbf24' }}></i>
        </div>
        <div className={styles.statInfo}>
          <div className={styles.statLabel}>Đánh giá TB</div>
          <div className={styles.statValue}>{stats.averageRating.toFixed(1)}</div>
        </div>
      </div>
    </div>
  );
};
