interface LoginResponse {
  token: string;
  user: User;
}

export const authService = {
  /**
   * Login with username and password
   */
  async login(username: string, password: string): Promise<LoginResponse> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      
      const account = MOCK_ACCOUNTS.find(
        (acc) => acc.username === username && acc.password === password
      );
      
      if (!account) {
        throw new Error('Tên đăng nhập hoặc mật khẩu không đúng');
      }
      
      return {
        token: `mock_token_${account.user.id}_${Date.now()}`,
        user: account.user,
      };
    }

    return apiClient.post<LoginResponse>('/auth/login', {
      username,
      password,
    });
  },

  /**
   * Logout current user
   */
  async logout(): Promise<void> {
    if (USE_MOCK_DATA) {
      await mockDelay(200);
      return;
    }

    return apiClient.post<void>('/auth/logout');
  },

  /**
   * Get current authenticated user
   */
  async getCurrentUser(): Promise<User> {
    if (USE_MOCK_DATA) {
      await mockDelay(300);
      
      // Try to get from localStorage
      const userStr = localStorage.getItem('auth_user');
      if (userStr) {
        return JSON.parse(userStr);
      }
      
      // Return default staff user if no user in localStorage
      return MOCK_ACCOUNTS[2].user; // Default to staff
    }

    return apiClient.get<User>('/auth/me');
  },

  /**
   * Check if user has specific role
   */
  hasRole(user: User | null, role: UserRole): boolean {
    return user?.role === role;
  },

  /**
   * Check if user has any of the specified roles
   */
  hasAnyRole(user: User | null, roles: UserRole[]): boolean {
    return user ? roles.includes(user.role) : false;
  },

  /**
   * Check if user is manager or admin
   */
  isManagerOrAdmin(user: User | null): boolean {
    return this.hasAnyRole(user, [UserRole.Manager, UserRole.Admin]);
  },
};

