import React, { useState, useRef, useEffect } from 'react';
import { Task, TaskStatus } from '../../../models/Task';
import { useAppDispatch } from '../../../store/hooks';
import { updateTask } from '../../../store/slices/tasksSlice';
import { KanbanColumn } from './KanbanColumn';
import styles from './KanbanBoard.module.css';

interface KanbanBoardProps {
  tasks: Task[];
  loading: boolean;
  onTaskClick: (task: Task) => void;
  onUpdateSuccess: () => void;
}

export const KanbanBoard: React.FC<KanbanBoardProps> = ({
  tasks,
  loading,
  onTaskClick,
  onUpdateSuccess,
}) => {
  const dispatch = useAppDispatch();
  const [draggedTask, setDraggedTask] = useState<Task | null>(null);
  const [showLeftArrow, setShowLeftArrow] = useState(false);
  const [showRightArrow, setShowRightArrow] = useState(false);
  const [isPanning, setIsPanning] = useState(false);
  const [startX, setStartX] = useState(0);
  const [scrollLeft, setScrollLeft] = useState(0);
  const boardRef = useRef<HTMLDivElement>(null);
  const columnRefs = useRef<(HTMLDivElement | null)[]>([]);

  const columns = [
    {
      id: TaskStatus.Assigned,
      title: 'Đã giao',
      icon: 'fa-user-check',
      color: 'var(--gray-600)',
    },
    {
      id: TaskStatus.InProgress,
      title: 'Đang thực hiện',
      icon: 'fa-spinner',
      color: 'var(--primary-color)',
    },
    {
      id: TaskStatus.UnderReview,
      title: 'Xem xét',
      icon: 'fa-check-circle',
      color: '#92400e',
    },
    {
      id: TaskStatus.Completed,
      title: 'Hoàn thành',
      icon: 'fa-check-double',
      color: '#065f46',
    },
  ];

  const getTasksForColumn = (status: TaskStatus) => {
    return tasks.filter((task) => task.status === status);
  };

  const handleDragStart = (task: Task) => {
    setDraggedTask(task);
  };

  const handleDragEnd = () => {
    setDraggedTask(null);
  };

  const handleDrop = async (targetStatus: TaskStatus) => {
    if (!draggedTask || draggedTask.status === targetStatus) {
      return;
    }

    try {
      await dispatch(
        updateTask({
          id: draggedTask.id,
          data: { status: targetStatus },
        })
      ).unwrap();
      onUpdateSuccess();
    } catch (error) {
      console.error('Failed to update task status:', error);
    }
  };

  /**
   * Check if board overflows and update arrow visibility
   */
  const checkOverflow = () => {
    const container = boardRef.current;
    if (!container) return;

    const hasOverflow = container.scrollWidth > container.clientWidth;

    if (hasOverflow) {
      updateArrowsVisibility();
    } else {
      setShowLeftArrow(false);
      setShowRightArrow(false);
    }
  };

  /**
   * Update arrows based on scroll position
   */
  const updateArrowsVisibility = () => {
    const container = boardRef.current;
    if (!container) return;

    const scrollLeft = container.scrollLeft;
    const maxScroll = container.scrollWidth - container.clientWidth;

    setShowLeftArrow(scrollLeft > 5);
    setShowRightArrow(scrollLeft < maxScroll - 5);
  };

  /**
   * Scroll board left or right to show next/previous hidden column
   */
  const scrollBoard = (direction: 'left' | 'right') => {
    const container = boardRef.current;
    if (!container) return;

    const containerRect = container.getBoundingClientRect();

    // Find first hidden column in the direction
    let targetIndex = -1;

    if (direction === 'right') {
      // Find first column that's partially or fully hidden on the right
      for (let i = 0; i < columnRefs.current.length; i++) {
        const col = columnRefs.current[i];
        if (col) {
          const colRect = col.getBoundingClientRect();
          if (colRect.right > containerRect.right) {
            targetIndex = i;
            break;
          }
        }
      }
    } else {
      // Find first column that's partially or fully hidden on the left
      for (let i = columnRefs.current.length - 1; i >= 0; i--) {
        const col = columnRefs.current[i];
        if (col) {
          const colRect = col.getBoundingClientRect();
          if (colRect.left < containerRect.left) {
            targetIndex = i;
            break;
          }
        }
      }
    }

    // Scroll to the target column
    if (targetIndex >= 0) {
      const targetColumn = columnRefs.current[targetIndex];
      if (targetColumn) {
        targetColumn.scrollIntoView({
          behavior: 'smooth',
          block: 'nearest',
          inline: 'start',
        });
      }
    }
  };

  /**
   * Handle mouse/touch pan to scroll
   */
  const handleMouseDown = (e: React.MouseEvent) => {
    const container = boardRef.current;
    if (!container) return;

    setIsPanning(true);
    setStartX(e.pageX - container.offsetLeft);
    setScrollLeft(container.scrollLeft);
    container.style.cursor = 'grabbing';
    container.style.userSelect = 'none';
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isPanning) return;
    e.preventDefault();
    
    const container = boardRef.current;
    if (!container) return;

    const x = e.pageX - container.offsetLeft;
    const walk = (x - startX) * 1.5; // Scroll speed multiplier
    container.scrollLeft = scrollLeft - walk;
  };

  const handleMouseUp = () => {
    setIsPanning(false);
    const container = boardRef.current;
    if (container) {
      container.style.cursor = 'grab';
      container.style.userSelect = '';
    }
  };

  const handleMouseLeave = () => {
    if (isPanning) {
      setIsPanning(false);
      const container = boardRef.current;
      if (container) {
        container.style.cursor = 'grab';
        container.style.userSelect = '';
      }
    }
  };

  /**
   * Setup scroll and resize listeners
   */
  useEffect(() => {
    const container = boardRef.current;
    if (!container) return;

    // Initial check
    checkOverflow();

    // Handle scroll events
    const handleScroll = () => updateArrowsVisibility();
    container.addEventListener('scroll', handleScroll);

    // Handle window resize
    window.addEventListener('resize', checkOverflow);

    return () => {
      container.removeEventListener('scroll', handleScroll);
      window.removeEventListener('resize', checkOverflow);
    };
  }, [tasks]);

  if (loading) {
    return (
      <div className={styles.loading}>
        <i className="fas fa-spinner fa-spin"></i> Đang tải...
      </div>
    );
  }

  return (
    <div className={styles.kanbanContainer}>
      {/* Left Arrow */}
      <button
        className={`${styles.navArrow} ${styles.navArrowLeft} ${showLeftArrow ? styles.visible : ''}`}
        onClick={() => scrollBoard('left')}
        aria-label="Scroll left"
        type="button"
      >
        <i className="fas fa-chevron-left"></i>
      </button>

      {/* Board Wrapper */}
      <div className={styles.boardWrapper}>
        <div 
          ref={boardRef} 
          className={styles.kanbanBoard}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseLeave}
          style={{ cursor: isPanning ? 'grabbing' : 'grab' }}
        >
          {columns.map((column, index) => (
            <KanbanColumn
              key={column.id}
              ref={(el) => (columnRefs.current[index] = el)}
              title={column.title}
              icon={column.icon}
              color={column.color}
              tasks={getTasksForColumn(column.id)}
              status={column.id}
              onDragStart={handleDragStart}
              onDragEnd={handleDragEnd}
          onDrop={handleDrop}
          onTaskClick={onTaskClick}
        />
      ))}
        </div>
      </div>

      {/* Right Arrow */}
      <button
        className={`${styles.navArrow} ${styles.navArrowRight} ${showRightArrow ? styles.visible : ''}`}
        onClick={() => scrollBoard('right')}
        aria-label="Scroll right"
        type="button"
      >
        <i className="fas fa-chevron-right"></i>
      </button>
    </div>
  );
};
