import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import { login, clearError } from '../../store/slices/authSlice';
import { addToast } from '../../store/slices/uiSlice';
import styles from './LoginPage.module.css';
import { Button } from '../../components/common/Button';
import { Card } from '../../components/common/Card';
import { Input } from '../../components/common/Input';
import { MOCK_LOGIN_ACCOUNTS } from '../../services/authService';

const LoginPage: React.FC = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const { loading, error, isAuthenticated, user } = useAppSelector((state) => state.auth);
  
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');

  useEffect(() => {
    // Redirect if already authenticated
    if (isAuthenticated && user) {
      navigate('/tickets');
    }
  }, [isAuthenticated, user, navigate]);

  useEffect(() => {
    // Clear any previous errors when component mounts
    dispatch(clearError());
  }, [dispatch]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!username || !password) {
      dispatch(addToast({
        message: 'Vui lòng nhập tên đăng nhập và mật khẩu',
        type: 'error',
      }));
      return;
    }

    try {
      await dispatch(login({ username, password })).unwrap();
      dispatch(addToast({
        message: 'Đăng nhập thành công!',
        type: 'success',
      }));
      // Navigation will happen via useEffect
    } catch (error: any) {
      // Error is handled by the reducer and displayed in the form
      console.error('Login failed:', error);
    }
  };

  const handleQuickLogin = async (user: typeof MOCK_LOGIN_ACCOUNTS[0]) => {
    setUsername(user.username);
    setPassword(user.password);
    
    try {
      await dispatch(login({ username: user.username, password: user.password })).unwrap();
      dispatch(addToast({
        message: `Đăng nhập thành công với vai trò ${user.role === 'manager' ? 'Quản lý' : user.role === 'admin' ? 'Admin' : 'Nhân viên'}!`,
        type: 'success',
      }));
    } catch (error: any) {
      console.error('Quick login failed:', error);
    }
  };

  return (
    <div className={styles.container}>
      <Card className={styles.card}>
        <div className={styles.logo}>
          <i className="fas fa-hospital-user"></i>
        </div>
        <h1 className={styles.title}>QLCV Y Khoa</h1>
        <p className={styles.subtitle}>Hệ Thống Quản Lý Công Việc</p>

        <form onSubmit={handleLogin} className={styles.form}>
          {error && (
            <div className={styles.errorMessage}>
              <i className="fas fa-exclamation-circle"></i>
              <span>{error}</span>
            </div>
          )}

          <div className={styles.inputGroup}>
            <label htmlFor="username">Tên đăng nhập</label>
            <Input
              id="username"
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              placeholder="Nhập tên đăng nhập"
              required
              autoComplete="username"
              disabled={loading}
            />
          </div>

          <div className={styles.inputGroup}>
            <label htmlFor="password">Mật khẩu</label>
            <Input
              id="password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Nhập mật khẩu"
              required
              autoComplete="current-password"
              disabled={loading}
            />
          </div>

          <Button type="submit" fullWidth loading={loading} disabled={!username || !password}>
            {loading ? 'Đang đăng nhập...' : 'Đăng nhập'}
          </Button>
        </form>

        {/* Development Helper - Quick Login Buttons */}
        {MOCK_LOGIN_ACCOUNTS.length > 0 && (
          <>
            <div className={styles.divider}>
              <span>Hoặc đăng nhập nhanh (Test)</span>
            </div>

            <div className={styles.quickLogin}>
              {MOCK_LOGIN_ACCOUNTS.map((account) => (
                <Button
                  key={account.username}
                  variant="secondary"
                  size="sm"
                  onClick={() => handleQuickLogin(account)}
                  disabled={loading}
                >
                  {account.role === 'admin' && <i className="fas fa-user-shield"></i>}
                  {account.role === 'manager' && <i className="fas fa-user-tie"></i>}
                  {account.role === 'staff' && <i className="fas fa-user"></i>}
                  {' '}
                  {account.role === 'admin' ? 'Admin' : account.role === 'manager' ? 'Quản lý' : 'Nhân viên'}
                  {account.username.includes('2') && ' 2'}
                </Button>
              ))}
            </div>

            <div className={styles.devHint}>
              <i className="fas fa-info-circle"></i>
              <small>Test accounts: admin/admin123, manager/manager123, staff/staff123</small>
            </div>
          </>
        )}
      </Card>
    </div>
  );
};

export default LoginPage;
