import React, { useState } from 'react';
import { useAppDispatch } from '../../../../store/hooks';
import { createTicket } from '../../../../store/slices/ticketsSlice';
import {
  resetCreateTicketForm,
  addToast,
} from '../../../../store/slices/uiSlice';
import { TicketPriority } from '../../../../models/Ticket';
import { Input } from '../../../../components/common/Input';
import { TextArea } from '../../../../components/common/TextArea';
import { Select, SelectOption } from '../../../../components/common/Select';
import { Checkbox } from '../../../../components/common/Checkbox';
import { Button } from '../../../../components/common/Button';
import { FormActions } from '../../../../components/common/FormActions';
import { FileUploadArea } from '../../../../components/common/FileUploadArea';
import styles from './CreateTicketForm.module.css';

export interface CreateTicketFormProps {
  onSuccess: () => void;
  onCancel: () => void;
}

// Mock department data - replace with actual API call
const departments: SelectOption[] = [
  { value: '1', label: 'IT' },
  { value: '2', label: 'Hành chính' },
  { value: '3', label: 'Nhân sự' },
  { value: '4', label: 'Kế toán' },
];

const priorityOptions: SelectOption[] = [
  { value: TicketPriority.Emergency, label: 'Khẩn cấp' },
  { value: TicketPriority.High, label: 'Cao' },
  { value: TicketPriority.Medium, label: 'Trung bình' },
  { value: TicketPriority.Low, label: 'Thấp' },
];

const typeOptions: SelectOption[] = [
  { value: 'incident', label: 'Sự cố' },
  { value: 'request', label: 'Yêu cầu' },
  { value: 'question', label: 'Câu hỏi' },
  { value: 'feedback', label: 'Góp ý' },
];

export const CreateTicketForm: React.FC<CreateTicketFormProps> = ({
  onSuccess,
  onCancel,
}) => {
  const dispatch = useAppDispatch();

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [priority, setPriority] = useState<string>('');
  const [type, setType] = useState<string>('');
  const [departmentId, setDepartmentId] = useState<string>('');
  const [location, setLocation] = useState('');
  const [files, setFiles] = useState<File[]>([]);
  const [urgent, setUrgent] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const validate = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!title.trim()) {
      newErrors.title = 'Vui lòng nhập tiêu đề';
    }

    if (!description.trim()) {
      newErrors.description = 'Vui lòng nhập mô tả';
    }

    if (!priority) {
      newErrors.priority = 'Vui lòng chọn độ ưu tiên';
    }

    if (!type) {
      newErrors.type = 'Vui lòng chọn loại phiếu';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validate()) {
      return;
    }

    setLoading(true);

    try {
      const ticketData = {
        title: title.trim(),
        description: description.trim(),
        priority: priority as TicketPriority,
        type,
        departmentId: departmentId || undefined,
        location: location.trim() || undefined,
        urgent,
        // Note: File upload is collected via FileUploadArea but not sent to API yet.
        // In production, files would need to be:
        // 1. Uploaded separately to get file URLs/IDs, or
        // 2. Sent as multipart/form-data with the ticket data
        // For now, the UI collects files for future implementation.
      };

      await dispatch(createTicket(ticketData)).unwrap();

      dispatch(
        addToast({
          message: 'Tạo phiếu yêu cầu thành công',
          type: 'success',
        })
      );

      dispatch(resetCreateTicketForm());
      onSuccess();
    } catch (error: any) {
      dispatch(
        addToast({
          message: error.message || 'Có lỗi xảy ra khi tạo phiếu',
          type: 'error',
        })
      );
    } finally {
      setLoading(false);
    }
  };

  const handleReset = () => {
    setTitle('');
    setDescription('');
    setPriority('');
    setType('');
    setDepartmentId('');
    setLocation('');
    setFiles([]);
    setUrgent(false);
    setErrors({});
    dispatch(resetCreateTicketForm());
    onCancel();
  };

  return (
    <form onSubmit={handleSubmit} className={styles.form}>
      <div className={styles.formContent}>
        <Input
          label="Tiêu đề"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Nhập tiêu đề phiếu yêu cầu"
          required
          fullWidth
          error={errors.title}
        />

        <TextArea
          label="Mô tả"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="Mô tả chi tiết vấn đề hoặc yêu cầu"
          required
          fullWidth
          rows={6}
          error={errors.description}
        />

        <div className={styles.row}>
          <Select
            label="Độ ưu tiên"
            value={priority}
            onChange={(e) => setPriority(e.target.value)}
            options={priorityOptions}
            placeholder="Chọn độ ưu tiên"
            required
            fullWidth
            error={errors.priority}
          />

          <Select
            label="Loại phiếu"
            value={type}
            onChange={(e) => setType(e.target.value)}
            options={typeOptions}
            placeholder="Chọn loại phiếu"
            required
            fullWidth
            error={errors.type}
          />
        </div>

        <div className={styles.row}>
          <Select
            label="Phòng ban"
            value={departmentId}
            onChange={(e) => setDepartmentId(e.target.value)}
            options={departments}
            placeholder="Chọn phòng ban (không bắt buộc)"
            fullWidth
          />

          <Input
            label="Vị trí"
            value={location}
            onChange={(e) => setLocation(e.target.value)}
            placeholder="Vị trí xảy ra sự cố (không bắt buộc)"
            fullWidth
          />
        </div>

        <div className={styles.uploadSection}>
          <label className={styles.sectionLabel}>Đính kèm file</label>
          <FileUploadArea
            value={files}
            onChange={setFiles}
            maxSize={10}
            maxFiles={5}
            accept="*/*"
          />
        </div>

        <div className={styles.checkboxSection}>
          <Checkbox
            label="Gửi thông báo khẩn cấp"
            checked={urgent}
            onChange={(e) => setUrgent(e.target.checked)}
            helperText="Gửi thông báo ngay lập tức đến người phụ trách"
          />
        </div>
      </div>

      <FormActions align="end">
        <Button type="button" variant="secondary" onClick={handleReset}>
          <i className="fas fa-times"></i>
          Hủy
        </Button>
        <Button type="submit" variant="primary" loading={loading}>
          <i className="fas fa-paper-plane"></i>
          Tạo phiếu
        </Button>
      </FormActions>
    </form>
  );
};
